'use client';
import Image from "next/image";
import { Button } from "@/components/ui/button";
import heroImage from "@/public/landing-page/hero-gym.jpg";

const HeroSection = () => {
  return (
    <section className="relative min-h-screen flex items-center justify-center">
      <div className="absolute inset-0">
        <Image
          src={heroImage}
          alt="Gym hero image"
          fill
          className="object-cover"
          priority
        />
        <div className="absolute inset-0 bg-black/70" />
      </div>
      <div className="container mx-auto px-6 text-center text-white relative z-10">
        <h1 className="text-6xl md:text-8xl font-black mb-6 tracking-tight">
          BE <span className="text-primary">STRONG</span>
        </h1>
        <p className="text-xl md:text-2xl mb-8 max-w-2xl mx-auto font-medium">
          Join The Best Gym In Town
        </p>
        <Button variant="gym" size="lg" className="text-lg px-8 py-6">
          Join Now
        </Button>
      </div>
    </section>
  );
};

export default HeroSection;